def confirm(self, order_id: str) -> Reservation:
    """Превращает активный резерв в отгрузку (расход по физическому остатку)."""
    record = self._find_reservation(order_id)
    now = self._clock.now()
    self._require_active(record, now)
    for (wh, sku), total in _group(record.lines).items():
        current = self._store.get_qty(wh, sku)
        if total > current:
            raise InsufficientStockError(wh, sku, total, current)
