def extend(self, order_id: str, ttl: timedelta) -> Reservation:
    """Продлевает активный резерв до ``now + ttl``; срок не сокращается."""
    _validate_ttl(ttl)
    record = self._find_reservation(order_id)
    now = self._clock.now()
    self._require_active(record, now)
    new_expires = now + ttl
    if new_expires > record.expires_at:
        record.expires_at = new_expires
        self._log.append(
            now, "RESERVE_EXTEND", order=order_id, expires=format_timestamp(new_expires)
        )
        logger.info("extended reservation %s", order_id)
    return self._snapshot(record, now)

